462:       rawTargetUrl = parsedReqUrl.searchParams.get('url');
463:     } catch (_) {}
464:   }
465: 
466:   const validation = validateTargetUrl(rawTargetUrl);
467:   if (!validation.valid) {
468:     res.writeHead(400, Object.assign({}, CORS_HEADERS, { 'Content-Type': 'application/json' }));
469:     res.end(JSON.stringify({ error: validation.error }));
470:     return;
471:   }
472: 
473:   const targetUrl = validation.url.href;
474: 
475:   // Track upstream request to abort on client disconnect
476:   let upstreamReq = null;
477:   req.on('close', () => {
478:     if (!res.writableEnded && upstreamReq) {
479:       upstreamReq.destroy();
480:     }
481:   });
