483:   const outboundHeaders = Object.assign({}, UPSTREAM_HEADERS);
484:   if (req.headers.range) outboundHeaders['Range'] = req.headers.range;
485:   if (req.headers['if-none-match']) outboundHeaders['If-None-Match'] = req.headers['if-none-match'];
486:   if (req.headers['if-modified-since']) outboundHeaders['If-Modified-Since'] = req.headers['if-modified-since'];
487: 
