489:     if (redirectCount > 5) {
490:       res.writeHead(502, Object.assign({}, CORS_HEADERS, { 'Content-Type': 'application/json' }));
491:       return res.end(JSON.stringify({ error: 'Too many redirects', url: currentUrl }));
492:     }
493: 
494:     const parsed = new URL(currentUrl);
495:     const client = parsed.protocol === 'https:' ? https : http;
496: 
497:     upstreamReq = client.request({
498:       protocol: parsed.protocol,
499:       hostname: parsed.hostname,
500:       port: parsed.port || (parsed.protocol === 'https:' ? 443 : 80),
501:       path: parsed.pathname + parsed.search,
502:       method: req.method,
503:       headers: outboundHeaders
504:     }, (upstreamRes) => {
505:       const statusCode = upstreamRes.statusCode;
506: 
507:       // Handle Redirects
508:       if ([301, 302, 303, 307, 308].indexOf(statusCode) !== -1 && upstreamRes.headers.location) {
509:         upstreamRes.resume();
